CREATE TABLE app_users(id uuid PRIMARY KEY,email text UNIQUE,phone text UNIQUE,password_hash text,is_guest boolean NOT NULL DEFAULT false,role text NOT NULL CHECK(role IN ('admin','seller','buyer')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),CHECK(email IS NOT NULL OR phone IS NOT NULL OR is_guest));
CREATE TABLE auth_sessions(id uuid PRIMARY KEY,family_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES app_users(id),client_type text NOT NULL CHECK(client_type IN ('web','native')),access_hash text UNIQUE NOT NULL,refresh_hash text UNIQUE NOT NULL,csrf_hash text NOT NULL,access_expires_at timestamptz NOT NULL,refresh_expires_at timestamptz NOT NULL,absolute_expires_at timestamptz NOT NULL,rotated_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX auth_sessions_family ON auth_sessions(family_id);
CREATE TABLE auth_limits(bucket text NOT NULL,window_start bigint NOT NULL,hits integer NOT NULL,PRIMARY KEY(bucket,window_start));
CREATE TABLE otp_challenges(id uuid PRIMARY KEY,phone text NOT NULL,provider_reference text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
